Here's a C++ program that uses a recursive function to generate the Fibonacci sequence, starting with two given integers as the first two sequence elements:

```cpp
#include <iostream>
#include <string>
#include <vector>

using namespace std;

// Recursive function to generate the Fibonacci sequence
vector<int> fibonacci(int n, int a, int b) {
    if (n == 0) {
        return vector<int>();
    }
    vector<int> result = fibonacci(n - 1, b, a + b);
    result.push_back(a);
    return result;
}

int main() {
    int n, a, b;
    cout << "Enter the first two integers: ";
    cin >> a >> b;
    cout << "Enter the number of sequence elements to generate: ";
    cin >> n;

    // Error handling for invalid inputs
    if (cin.fail() || n <= 0 || a < 0 || b < 0) {
        cerr << "Invalid input. Please enter valid integers and a positive number for the number of sequence elements." << endl;
        return 1;
    }

    vector<int> sequence = fibonacci(n, a, b);
    cout << "Fibonacci sequence: ";
    for (int i = 0; i < sequence.size(); i++) {
        cout << sequence[i] << (i < sequence.size() - 1 ? ", " : "");
    }
    cout << endl;

    return 0;
}
```

This program prompts the user to input the first two integers and the number of sequence elements to generate. It then uses the `fibonacci` function to generate the sequence and outputs it, with each element separated by a comma and a space. The program also includes error handling for invalid inputs, such as non-numeric inputs or negative numbers.

