```go
package main

import (
	"fmt"
	"io/ioutil"
	"log"
	"strings"

	"github.com/apache/avro/v2/schema"
)

type StructInfo struct {
	Name   string
	Fields []FieldInfo
}

type FieldInfo struct {
	Name    string
	Type    string
	Optional bool
}

func parseStruct(file string, structName string) (*Schema, error) {
	content, err := ioutil.ReadFile(file)
	if err != nil {
		return nil, fmt.Errorf("failed to read file: %w", err)
	}

	structLines := strings.Split(string(content), "\n")
	for _, line := range structLines {
		if strings.HasPrefix(line, fmt.Sprintf("%s:", structName)) {
			fields := make([]FieldInfo, 0)
			for _, fieldLine := range structLines[1:] {
				parts := strings.SplitN(fieldLine, ":", 2)
				if len(parts) == 2 {
					name := parts[0]
					typeStr := parts[1]
					optional := false
					if strings.HasSuffix(typeStr, "...") {
						typeStr = typeStr[:len(typeStr)-3]
						optional = true
					}
					fields = append(fields, FieldInfo{
						Name:    name,
						Type:    typeStr,
						Optional: optional,
					})
				}
			}
			return &Schema{
				Name:   structName,
				Fields: fields,
			}, nil
		}
