```csharp
using System;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;

public static string GetUsernameFromJwtToken(string token)
{
    var tokenHandler = new JwtSecurityTokenHandler();
    var key = Encoding.ASCII.Parse("your_secret_key"); // Replace this with your secret key
    var tokenDescriptor = new SecurityTokenDescriptor
    {
        TokenType = "Jwt",
        Issuer = "your_issuer",
        Audience = "your_audience",
        SigningKey = key,
        ExpiresUtc = DateTimeOffset.UtcNow.AddMinutes(60),
        Claims = new[]
        {
            new Claim(ClaimTypes.NameIdentifier, "username")
        }
    };

    var token = tokenHandler.ReadJwtToken(token, tokenDescriptor);
    return token.Claims.FirstOrDefault(c => c.Type == ClaimTypes.NameIdentifier)?.Value;
}
```

4. Finally, you can call the `GetUsernameFromJwtToken` method with the JWT token you want to parse:

```csharp
