Here's a C function that converts the command-line arguments (argv) to a null-terminated string:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char *convert_argv_to_cstring(int argc, char *argv[]) {
    char *cstring = malloc(sizeof(char) * (argc + 1));
    if (!cstring) {
        fprintf(stderr, "Error: Failed to allocate memory for the cstring\n");
        return NULL;
    }

    strcpy(cstring, "");
    for (int i = 0; i < argc; i++) {
        strcat(cstring, argv[i]);
        strcat(cstring, " ");
    }
    strcat(cstring, "\0");

    return cstring;
}

int main(int argc, char *argv[]) {
    char *cstring = convert_argv_to_cstring(argc, argv);
    if (!cstring) {
        return 1;
    }

    printf("The converted cstring is: %s\n", cstring);
    free(cstring);

    return 0;
}
```

This function takes the number of command-line arguments and the array of argument strings as input, allocates memory for a null-terminated string, copies the argument strings into the cstring, and returns it. Make sure to include the necessary header files and link with the required libraries when using this code.

