To modify the C++ code to retrieve data from Facebook's API, we need to replace the Twitter API calls with Facebook API calls. Since you don't want to use any external libraries, we'll have to handle the HTTP requests manually. Here's a modified version of the code:

```cpp
#include <iostream>
#include <curl/curl.h>
#include <string>
#include <vector>

using namespace std;

string getFacebookData(string accessToken) {
    string url = "https://graph.facebook.com/v10.0/me/posts?access_token=" + accessToken;
    CURL *curl;
    CURLcode res;
    vector<string> posts;

    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &posts);
        res = curl_easy_perform(curl);
        if (res != CURLE_OK)
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));

        curl_easy_cleanup(curl);
    }

    return posts.front();
}

int main() {
    string accessToken = "YOUR_ACCESS_TOKEN"; // Replace with your Facebook access token
    string data = getFacebookData(accessToken);

    cout << "Retrieved data from Facebook: " << data << endl;

    return 0;
}
```

Replace `YOUR_ACCESS_TOKEN` with your actual Facebook access token. This code will retrieve the latest post from your Facebook timeline. You can modify the URL and the request parameters to fetch different types of data or from different parts of Facebook.

